  --popover-foreground: hsl(300 50% 100%);
  --primary: hsl(300 50% 100%);
  --primary-foreground: hsl(0 0% 0%);
  --secondary: hsl(300 0% 13.15%);
  --secondary-foreground: hsl(300 50% 100%);
  --muted: hsl(0 0% 11.3%);
  --muted-foreground: hsl(300 0% 64.47%);
  --accent: hsl(0 0% 19.89%);
  --accent-foreground: hsl(300 50% 100%);
  --destructive: hsl(359.94 100% 67.89%);
  --destructive-foreground: hsl(0 0% 0%);
  --border: hsl(300 0% 14.09%);
  --input: hsl(0 0% 19.89%);
  --ring: hsl(300 0% 64.47%);
  --chart-1: hsl(40.25 100% 52.09%);
  --chart-2: hsl(218.16 90.04% 55.16%);
  --chart-3: hsl(0 0% 45.61%);
  --chart-4: hsl(330 0% 32.31%);
  --chart-5: hsl(0 0% 89.56%);
  --radius: 0.5rem;
  --sidebar: hsl(0 0% 6.87%);
  --sidebar-foreground: hsl(300 50% 100%);
  --sidebar-primary: hsl(300 50% 100%);
  --sidebar-primary-foreground: hsl(0 0% 0%);
  --sidebar-accent: hsl(0 0% 19.89%);
  --sidebar-accent-foreground: hsl(300 50% 100%);
  --sidebar-border: hsl(0 0% 19.89%);
  --sidebar-ring: hsl(300 0% 64.47%);
  --font-sans: Geist, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: Geist Mono, monospace;
  --shadow-color: hsl(0 0% 0%);
  --shadow-opacity: 0.18;
  --shadow-blur: 2px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 1px 2px 0px hsl(0 0% 0% / 0.09);
  --shadow-xs: 0px 1px 2px 0px hsl(0 0% 0% / 0.09);
  --shadow-sm:
    0px 1px 2px 0px hsl(0 0% 0% / 0.18), 0px 1px 2px -1px hsl(0 0% 0% / 0.18);
  --shadow:
    0px 1px 2px 0px hsl(0 0% 0% / 0.18), 0px 1px 2px -1px hsl(0 0% 0% / 0.18);
  --shadow-md:
    0px 1px 2px 0px hsl(0 0% 0% / 0.18), 0px 2px 4px -1px hsl(0 0% 0% / 0.18);
  --shadow-lg:
    0px 1px 2px 0px hsl(0 0% 0% / 0.18), 0px 4px 6px -1px hsl(0 0% 0% / 0.18);
  --shadow-xl:
    0px 1px 2px 0px hsl(0 0% 0% / 0.18), 0px 8px 10px -1px hsl(0 0% 0% / 0.18);
  --shadow-2xl: 0px 1px 2px 0px hsl(0 0% 0% / 0.45);
}
